import{_ as a,o as i,c as l,a3 as c}from"./chunks/framework.DAK02U1-.js";const b=JSON.parse('{"title":"从源码构建","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"从源码构建 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/guide/build"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/guide/build"}],["meta",{"name":"twitter:card","content":"summary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/guide/build"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/guide/build"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/guide/build"}]]},"headers":[],"relativePath":"zh/clice/guide/build.md","filePath":"zh/clice/guide/build.md","lastUpdated":1794738697000}'),t={name:"zh/clice/guide/build.md"};function o(d,e,r,s,n,p){return i(),l("div",null,[...e[0]||(e[0]=[c('<h1 id="build-from-source" tabindex="-1"><span id="从源码构建" class="heading-alias"></span>从源码构建 <a class="header-anchor" href="#build-from-source" aria-label="Permalink to &quot;从源码构建&quot;">​</a></h1><p>clice 仅用 <a href="https://bazel.build" target="_blank" rel="noreferrer">Bazel</a> 即可构建。构建所需的一切均由 Bazel 自行下载：clice-io 的 clang 工具链 <a href="https://github.com/clice-io/xclang" target="_blank" rel="noreferrer">xclang</a> 同一发布版本中的 C++ 工具链与预编译 LLVM/Clang 库，以及 clice 链接的其余库。仓库中的 pixi 和 npm 用于配置测试和文档所需的工具，构建 clice 本身两者都不需要。</p><h2 id="requirements" tabindex="-1"><span id="环境要求" class="heading-alias"></span>环境要求 <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><ul><li><p>Bazel，通过 <a href="https://github.com/bazelbuild/bazelisk" target="_blank" rel="noreferrer">bazelisk</a> 运行，后者会拉取 <code>.bazelversion</code> 指定的版本。</p></li><li><p><code>PATH</code> 中需有 git 和 <a href="https://nodejs.org" target="_blank" rel="noreferrer">Node.js</a>：构建会调用 Node 脚本，把 <code>git describe</code> 得出的版本号写入 clice。</p></li><li><p>Windows 上还需要 Bash（<a href="https://gitforwindows.org" target="_blank" rel="noreferrer">Git for Windows</a> 自带）以及较短的 Bazel 输出根目录，因为 Bazel 默认的输出根目录层级过深，会超出 Windows 路径长度限制。将其写入 <code>%USERPROFILE%\\.bazelrc</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>startup --output_user_root=C:/b</span></span></code></pre></div></li></ul><h2 id="building" tabindex="-1"><span id="构建" class="heading-alias"></span>构建 <a class="header-anchor" href="#building" aria-label="Permalink to &quot;构建&quot;">​</a></h2><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bazel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> //:bin/clice</span></span></code></pre></div><p>构建出的 clice 位于 <code>build/RelWithDebInfo/bin/bin/clice</code>，同级还有资源目录 <code>build/RelWithDebInfo/bin/lib/clang</code>，clice 从中读取 clang 的头文件。</p><p>各构建类型对应不同的配置，每种配置各有独立目录 <code>build/&lt;type&gt;</code>：</p><table tabindex="0"><thead><tr><th>配置</th><th>作用</th></tr></thead><tbody><tr><td><code>--config=RelWithDebInfo</code></td><td>默认配置：开启优化，附带调试信息</td></tr><tr><td><code>--config=Debug</code></td><td>轻度优化（<code>-O1</code>）并启用 Address Sanitizer，支持 x86_64 Linux 和 arm64 macOS</td></tr></tbody></table><p><code>--platforms=@xclang//platforms:&lt;triple&gt;</code> 可为其他目标平台构建：在 x86_64 Linux 上可构建其余所有目标平台，例如 <code>--platforms=@xclang//platforms:aarch64-apple-darwin</code>。</p><p>LLVM/Clang 库中存放的是 ThinLTO bitcode，每次链接程序都会重新执行其代码生成，单个程序耗时数分钟。lld 会将生成结果缓存在 <code>/var/tmp/xclang-thinlto</code>（Windows 上为 <code>C:/xclang-thinlto</code>），后续链接只需数秒。</p><p><code>bazel build //:package //:symbols</code> 会构建发布归档包与符号包（其中包含供 <code>scripts/symbolize.py</code> 读取的 <code>clice.gsym</code>），产物为 <code>build/&lt;type&gt;/bin</code> 下的 <code>clice.tar.gz</code> 和 <code>clice-symbol.tar.xz</code>（Windows 上为 <code>.zip</code>）。</p><h2 id="working-on-clice" tabindex="-1"><span id="开发-clice" class="heading-alias"></span>开发 clice <a class="header-anchor" href="#working-on-clice" aria-label="Permalink to &quot;开发 clice&quot;">​</a></h2><p><code>bazel run @compdb//:refresh -- --output_groups=+compilation_prerequisites_INTERNAL_</code> 会在仓库根目录生成 clice 自身源码的 <code>compile_commands.json</code>，以便用 clice 开发其自身代码；该输出组还会构建各编译命令读取的生成头文件。</p><p>运行测试需要 pixi 安装的工具。<code>bazel build //:dist</code> 会构建 clice 及单元测试，随后 <code>pixi run test</code> 会运行单元测试与测试用例（Debug 构建使用 <code>--config=Debug</code> 和 <code>pixi run test Debug</code>）；测试用例的编写方法见 <a href="https://github.com/clice-io/clice/blob/main/tests/README.md" target="_blank" rel="noreferrer"><code>tests/README.md</code></a>。</p><h2 id="another-llvm-build" tabindex="-1"><span id="使用其他-llvm-构建" class="heading-alias"></span>使用其他 LLVM 构建 <a class="header-anchor" href="#another-llvm-build" aria-label="Permalink to &quot;使用其他 LLVM 构建&quot;">​</a></h2><p>clice 链接其开发时所针对的确切版本的 LLVM/Clang 库，不能使用系统自带的版本。若要换用自行构建的库来替代发布版本，可传入 <code>--repo_env=XCLANG_LIBCLANG_ROOT=&lt;directory&gt;</code>（ASan 版本使用 <code>XCLANG_LIBCLANG_ASAN_ROOT</code>）；该库必须采用与 xclang 相同的方式构建，即运行 xclang 的 <code>scripts/toolchain.ts</code>。</p>',17)])])}const u=a(t,[["render",o]]);export{b as __pageData,u as default};
